# Let me examine patterns more systematically
grid = [
    [8, 8, 8, 0, 3, 5, 0, 5, 5, 3, 9, 0, 0, 0, 3, 0, 0, 0, 0],
    [8, 0, 8, 8, 3, 5, 5, 5, 5, 3, 0, 0, 9, 9, 3, 4, 4, 0, 4],
    [8, 0, 0, 8, 3, 5, 0, 5, 5, 3, 0, 0, 0, 9, 3, 0, 4, 0, 4],
    [0, 0, 8, 8, 3, 5, 0, 5, 5, 3, 0, 0, 0, 9, 3, 0, 4, 0, 4]
]

# Extract each section as 4x4 matrices
left_section = []
midleft_section = []
midright_section = []
right_section = []

for row in grid:
    left_section.append(row[0:4])
    midleft_section.append(row[5:9])
    midright_section.append(row[10:14])
    right_section.append(row[15:19])

print("=== Section matrices (each section is 4x4) ===")
print("\nLeft:")
for row in left_section:
    print(' '.join(f'{v:>2}' for v in row))

print("\nMid-Left:")
for row in midleft_section:
    print(' '.join(f'{v:>2}' for v in row))

print("\nMid-Right:")
for row in midright_section:
    print(' '.join(f'{v:>2}' for v in row))

print("\nRight:")
for row in right_section:
    print(' '.join(f'{v:>2}' for v in row))

# Now let me check some relationships
print("\n=== Relationship analysis ===")

# Check if sections are related by arithmetic operations
# For example: Left + something = MidLeft?

def cell_rel(s1, s2):
    """Compute relationship between two 4x4 sections"""
    rels = {}
    for r in range(4):
        for c in range(4):
            v1, v2 = s1[r][c], s2[r][c]
            if v1 == 0 and v2 == 0:
                continue  # Skip both zeros
            if v2 == 0:
                rels.setdefault('s1_active', set()).add(v1)
            elif v1 == 0:
                rels.setdefault('s2_active', set()).add(v2)
            else:
                rels.setdefault('both_active', set()).add(v1 * v2)
    return rels

print("\nChecking overlaps...")
for s1_name, s1 in [("Left", left_section), ("Mid-Left", midleft_section), ("Mid-Right", midright_section), ("Right", right_section)]:
    for s2_name, s2 in [("Left", left_section), ("Mid-Left", midleft_section), ("Mid-Right", midright_section), ("Right", right_section)]:
        if s1_name >= s2_name:
            continue
        rel = cell_rel(s1, s2)
        if 'both_active' in rel:
            print(f"{s1_name} and {s2_name}: both non-zero in { ' , '.join(str(r)+str(c) for r in range(4) for c in range(4) if s1[r][c]!=0 and s2[r][c]!=0) }")

